import { describe, it, expect } from 'vitest';
import { latLonToVector3, buildGlobe } from '../src/globe.js';

const RADIUS = 5;
const EPS = 1e-9;

const cities = [
  ['Quito', -0.18, -78.47],
  ['Reykjavik', 64.15, -21.94],
  ['Singapore', 1.35, 103.82],
  ['Sydney', -33.87, 151.21],
];

describe('buildGlobe markers', () => {
  it('creates one named marker per city', () => {
    const globe = buildGlobe({ radius: RADIUS });
    for (const [name] of cities) {
      const marker = globe.getObjectByName(name);
      expect(marker).toBeDefined();
    }
  });

  it('every marker lies on the sphere surface (distance from center == radius)', () => {
    const globe = buildGlobe({ radius: RADIUS });
    for (const [name] of cities) {
      const marker = globe.getObjectByName(name);
      const dist = marker.position.length();
      expect(Math.abs(dist - RADIUS)).toBeLessThanOrEqual(EPS);
    }
  });

  it('Quito sits essentially on the equator (|y| < radius * 0.01)', () => {
    const globe = buildGlobe({ radius: RADIUS });
    const quito = globe.getObjectByName('Quito');
    expect(Math.abs(quito.position.y)).toBeLessThan(RADIUS * 0.01);
  });

  it('Reykjavik has the greatest y (northernmost city)', () => {
    const globe = buildGlobe({ radius: RADIUS });
    const ys = cities.map(([name]) => globe.getObjectByName(name).position.y);
    const reykjavikY = globe.getObjectByName('Reykjavik').position.y;
    expect(reykjavikY).toBeGreaterThan(Math.max(...ys.filter((_, i) => i !== 1)));
  });

  it('latLonToVector3(90, 0, r) is exactly the north pole (0, r, 0)', () => {
    const v = latLonToVector3(90, 0, RADIUS);
    expect(v.x).toBeCloseTo(0, 12);
    expect(v.y).toBeCloseTo(RADIUS, EPS);
    expect(v.z).toBeCloseTo(0, 12);
  });

  it('longitudes ±90 are mirror images in x with equal z', () => {
    const east = latLonToVector3(0, 90, RADIUS);
    const west = latLonToVector3(0, -90, RADIUS);
    expect(east.x + west.x).toBeCloseTo(0, 12);
    expect(east.z - west.z).toBeCloseTo(0, 12);
  });
});

