import * as THREE from 'three';

const DEG = Math.PI / 180;

/**
 * Convert geographic coordinates to a position on a sphere.
 *
 * Convention:
 *   - y = sin(lat)  (latitude measured from the equator, north positive)
 *   - longitude 0 lies on the +z axis
 *   - east positive: increasing longitude rotates toward +x
 *
 * x = cos(lat) * sin(lon)
 * y = sin(lat)
 * z = cos(lat) * cos(lon)
 *
 * @param {number} latDeg latitude in degrees
 * @param {number} lonDeg longitude in degrees (east positive)
 * @param {number} radius sphere radius
 * @returns {THREE.Vector3} point on the sphere of the given radius
 */
export function latLonToVector3(latDeg, lonDeg, radius) {
  const lat = latDeg * DEG;
  const lon = lonDeg * DEG;
  const cosLat = Math.cos(lat);
  return new THREE.Vector3(
    cosLat * Math.sin(lon) * radius,
    Math.sin(lat) * radius,
    cosLat * Math.cos(lon) * radius,
  );
}

/**
 * Build a globe: a sphere plus one small marker sphere per city.
 *
 * @param {object} [options]
 * @param {number} [options.radius=5] globe radius
 * @param {Array<{name: string, lat: number, lon: number}>} [options.cities]
 *   cities to mark; defaults to an inline list.
 * @returns {THREE.Group} group containing the globe and all markers
 */
export function buildGlobe({ radius = 5, cities = DEFAULT_CITIES } = {}) {
  const globe = new THREE.Group();

  const sphereGeometry = new THREE.SphereGeometry(radius, 64, 48);
  const sphereMaterial = new THREE.MeshStandardMaterial({
    color: 0x2244aa,
    roughness: 0.8,
  });
  globe.add(new THREE.Mesh(sphereGeometry, sphereMaterial));

  for (const { name, lat, lon } of cities) {
    const marker = new THREE.Mesh(
      new THREE.SphereGeometry(radius * 0.02, 16, 12),
      new THREE.MeshBasicMaterial({ color: 0xff4444 }),
    );
    marker.name = name;
    marker.position.copy(latLonToVector3(lat, lon, radius));
    globe.add(marker);
  }

  return globe;
}

const DEFAULT_CITIES = [
  { name: 'Quito', lat: -0.18, lon: -78.47 },
  { name: 'Reykjavik', lat: 64.15, lon: -21.94 },
  { name: 'Singapore', lat: 1.35, lon: 103.82 },
  { name: 'Sydney', lat: -33.87, lon: 151.21 },
];

